{% macro is_incremental() %}
    {#-- do not run introspective queries in parsing #}
    {% if not execute %}
        {{ return(False) }}
    {% else %}
        {% set relation = adapter.get_relation(this.database, this.schema, this.table) %}
        {{ return(relation is not none
                  and relation.type == 'table'
                  and model.config.materialized == 'incremental'
                  and not should_full_refresh()) }}
    {% endif %}
{% endmacro %}

orders as (

    select * from {{ ref('int_orders__enriched') }}

    {% if is_incremental() %}
    -- only the orders loaded after the newest row already in this table
    -- (coalesce: if the table is empty, for example after --empty, max() is NULL -> take every row)
    where loaded_at > (select coalesce(max(loaded_at), '1900-01-01') from {{ this }})
    {% endif %}

),

{% if is_incremental() %}
where loaded_at >= (select {{ dbt.dateadd('day', -3, 'max(loaded_at)') }} from {{ this }})
{% endif %}

-- one column
{{ config(materialized='incremental', unique_key='order_id') }}
-- a list of columns
{{ config(materialized='incremental', unique_key=['order_id', 'product_id']) }}

-- append ignores unique_key: every run inserts the 3 rows again
{{ config(materialized='incremental', incremental_strategy='append', unique_key='k') }}

select * from (values (1, 'a'), (2, 'b'), (3, 'c')) as t(k, v)

-- the NEW rows contain the key 2 twice
{{ config(materialized='incremental', incremental_strategy='merge', unique_key='k') }}

{% if is_incremental() %}
select * from (values (2, 'new-1'), (2, 'new-2'), (3, 'c')) as t(k, v)
{% else %}
select * from (values (1, 'a'), (2, 'b')) as t(k, v)
{% endif %}

-- one row has a NULL key
{{ config(materialized='incremental', incremental_strategy='merge', unique_key='k') }}

select * from (values (1, 'a'), (null, 'no key')) as t(k, v)

{{
    config(
        materialized='incremental',
        unique_key='order_id',
        incremental_strategy='merge',
        incremental_predicates=["DBT_INTERNAL_DEST.order_date >= '2025-12-01'"]
    )
}}
